// mapelements/Supplements.js
import React, { useEffect, useState } from "react";
import { URL_START } from '../../data/config';

const Supplements = ({ map, openWindows, setOpenWindows, setWindowSize }) => {
  const [isVisible, setIsVisible] = useState(true);
  const [data, setData] = useState(null);

  useEffect(() => {
    if (!map) return;

    const fetchData = async () => {
      try {
        const response = await fetch(`${URL_START}/api/areas`);
        if (!response.ok) throw new Error(`HTTP error! Status: ${response.status}`);
        const data = await response.json();
        setData(data);
        addDataToMap(map, data);
      } catch (error) {
        console.error(`Failed fetching Supplements:`, error);
      }
    };

    fetchData();
    const interval = setInterval(fetchData, 8 * 60 * 1000);
    return () => clearInterval(interval);
  }, [map]);

  const addDataToMap = (map, data) => {
    if (!map.getSource("supplements")) {
      map.addSource("supplements", { type: "geojson", data });
    } else {
      map.getSource("supplements").setData(data);
    }

    if (!map.getLayer("supplements-layer")) {
      map.addLayer({
        id: "supplements-layer",
        type: "line",
        source: "supplements",
        filter: ["==", "active", true],
        paint: {
          "line-color": [
            "case",
            ["==", ["get", "alwaysActive"], true], "gray",
            ["==", ["get", "airspaceclass"], "TEMPO R"], "red",
            ["==", ["get", "airspaceclass"], "Restricted"], "red",
            ["==", ["get", "airspaceclass"], "TEMPO D"], "darkorange",
            ["==", ["get", "airspaceclass"], "Danger"], "darkorange",
            "gray",
          ],
          "line-width": [
            "case",
            ["==", ["get", "alwaysActive"], true], 1,
            1
          ],
          "line-opacity": [
            "case",
            ["==", ["slice", ["get", "name"], 0, 6], "EFINOB"], 0,
            1
          ],
          "line-dasharray": [
            "case",
            ["==", ["get", "activenow"], false], [1, 1],
            [1, 0]
          ],
        },
      });
      map.setLayoutProperty("supplements-layer", "visibility", isVisible ? "visible" : "none");
    }

    if (!map.getLayer("supplements-layer-fill")) {
      map.addLayer({
        id: "supplements-layer-fill",
        type: "fill",
        source: "supplements",
        filter: ["==", "activenow", true],
        paint: {
          "fill-color": [
            "case",
            ["==", ["get", "airspaceclass"], "TEMPO R"], "red",
            ["==", ["get", "airspaceclass"], "Restricted"], "red",
            ["==", ["get", "airspaceclass"], "TEMPO D"], "darkorange",
            ["==", ["get", "airspaceclass"], "Danger"], "darkorange",
            "gray",
          ],
          "fill-opacity": [
            "case",
            ["==", ["get", "alwaysActive"], true], 0,
            0.3
          ]
        },
      });
      map.setLayoutProperty("supplements-layer-fill", "visibility", isVisible ? "visible" : "none");
    }

    if (!map.getLayer("supplements-labels")) {
      map.addLayer({
        id: "supplements-labels",
        type: "symbol",
        source: "supplements",
        filter: ["all", ["==", "active", true]],
        layout: {
          "icon-image": [
            "case",
            ["==", ["slice", ["get", "code"], 0, 6], "EFINOB"], "obstacle",
            ""
          ],
          "text-field": [
            "case",
            ["==", ["slice", ["get", "code"], 0, 6], "EFINOB"], "",
            ["==", ["get", "alwaysActive"], true], "",
            ["get", "code"]
          ],
          "text-size": 9,
          "text-font": ["Open Sans Bold"],
          "text-allow-overlap": true,
          "icon-allow-overlap": true,
          "icon-size": 0.6,
        },
        paint: {
          "text-color": [
            "case",
            ["==", ["get", "airspaceclass"], "TEMPO R"], "darkred",
            ["==", ["get", "airspaceclass"], "Restricted"], "darkred",
            ["==", ["get", "airspaceclass"], "TEMPO D"], "brown",
            ["==", ["get", "airspaceclass"], "Danger"], "brown",
            "darkred"
          ],
          "text-halo-color": "white",
          "text-halo-width": 1,
        },
        minzoom: 5,
      });

      map.moveLayer('supplements-layer', 'lower-airspace');

      map.on("mouseenter", 'supplements-labels', () => {
        map.getCanvas().style.cursor = "pointer";
      });

      map.on("mouseleave", 'supplements-labels', () => {
        map.getCanvas().style.cursor = "default";
      });

      // Remove existing click event listener (if any)
      map.off('click', 'supplements-labels');

      // Add click event listener to the supplements-labels layer
      map.on('click', 'supplements-labels', (e) => {
        const properties = e.features[0].properties;
        const name = properties.name || "Supplement";
        const notams = properties.notams ? JSON.parse(properties.notams) : [];
        const notamTexts = notams.map(n => n.text).filter(Boolean);

        const lower = properties.lower;
        const upper = properties.upper;
      
        // Build the window content dynamically
        const content = (
          <div className="p-2 monospace-font text-sm overflow-y-auto mb-6" style={{ userSelect: 'text' }}>
            
            <div className="flex gap-2">
              <div className="pilotdepdest flex-1">{name}</div>
              {lower && upper && (
                <div className="pilotdepdest flex-1">{lower} - {upper}</div>
              )}
            </div>

            {notamTexts.length > 0 && (
              <div>
                <p className="pl-[2px]">RAW NOTAM{notamTexts.length > 1 ? 'S' : ''}</p>
                {notamTexts.map((text, idx) => (
                  <div key={idx} className="flightplan text-xs mb-2">
                    {text}
                  </div>
                ))}
              </div>
            )}
          </div>
        );
      
        setOpenWindows((prev) => {
          // Check if a window with the same name already exists
          const existingWindowIndex = prev.findIndex((win) => win.title === name);
      
          if (existingWindowIndex !== -1) {
            // Update the existing window
            const updatedWindows = [...prev];
            updatedWindows[existingWindowIndex] = {
              id: updatedWindows[existingWindowIndex].id, // Keep the same ID
              title: name,
              content: content,
            };
            return updatedWindows;
          } else {
            // Add a new window with a unique ID
            return [
              ...prev,
              {
                id: `supplement-window-${name}-${Date.now()}`,
                title: `SUPPLEMENT DETAILS`,
                content: content,
              },
            ];
          }
        });
        setWindowSize(2);
      });

      map.setLayoutProperty("supplements-labels", "visibility", isVisible ? "visible" : "none");
    }
  };

  const toggleVisibility = () => {
    if (!map) return;
    const visibility = isVisible ? "none" : "visible";
    map.setLayoutProperty("supplements-layer", "visibility", visibility);
    map.setLayoutProperty("supplements-layer-fill", "visibility", visibility);
    map.setLayoutProperty("supplements-labels", "visibility", visibility);
    setIsVisible(!isVisible);
  };

  return (
    <button
        data-tooltip-id="map-buttons-tooltip"
        data-tooltip-content="Supplements (R/D areas)"
        className={`w-8 h-8 ${isVisible ? "bg-gray-600" : "bg-gray-400"} text-white flex items-center justify-center`}
        onClick={toggleVisibility}
    >
        <span role="img" aria-label="Supplements" className="text-sm">R/D</span>
    </button>
  );
};

export default Supplements;